// Session-local, DOM-free mood instrumentation. No artwork or locomotion changes.
class CatMood {
  static keys=['playfulness','sleepiness','alertness'];
  static clamp(v){return Math.max(0,Math.min(1,Number.isFinite(Number(v))?Number(v):0));}
  constructor(id,profile={}){this.id=id;this.seed=Number.isFinite(profile.seed)?profile.seed>>>0:[...id].reduce((h,c)=>Math.imul(h^c.charCodeAt(0),16777619)>>>0,2166136261);this.randomState=this.seed;let state=this.seed;const variation=()=>{state=Math.imul(state^state>>>16,2246822507)>>>0;state=Math.imul(state^state>>>13,3266489909)>>>0;return (state^state>>>16)>>>0;};this.phase=variation()/4294967296*Math.PI*2;this.period=65+variation()/4294967296*75;this.baseline={playfulness:.28+variation()/4294967296*.4,sleepiness:.18+variation()/4294967296*.36,alertness:.18+variation()/4294967296*.34,...profile.baseline};for(const k of CatMood.keys)this.baseline[k]=CatMood.clamp(this.baseline[k]);this.reset();}
  reset(){this.values={...this.baseline};this.held=false;this.time=0;this.label='balanced';this.pending=null;this.since=0;this.lastEvent='Baseline';this.events=[];this.seen=new Set();this.randomState=this.seed;}
  random(){let t=this.randomState+=0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296;}
  set(key,value){if(!CatMood.keys.includes(key))return;this.values[key]=CatMood.clamp(value);this.held=true;this.lastEvent='Manual hold';this.updateLabel();}
  step(seconds,resting=false){const dt=Math.max(0,Math.min(.25,seconds||0));this.time+=dt;if(!this.held){const wave=Math.sin(this.phase+this.time*2*Math.PI/this.period);for(const k of CatMood.keys){const target=CatMood.clamp(k==='sleepiness'?(resting?.08:.5)+this.baseline[k]*.2:k==='playfulness'?this.baseline[k]+wave*.2+(resting?.08:-.04):this.baseline[k]+Math.sin(this.phase+this.time/23)*.1),tau=k==='alertness'?18:k==='sleepiness'?100:28;this.values[k]=CatMood.clamp(target+(this.values[k]-target)*Math.exp(-dt/tau));}}this.updateLabel();}
  experience(kind){if(this.held)return;const changes={notice:[.035,0,.08],play:[-.04,.035,.08],company:[0,.025,-.035]}[kind];if(!changes)return;CatMood.keys.forEach((k,i)=>this.values[k]=CatMood.clamp(this.values[k]+changes[i]));this.lastEvent={notice:'Noticed another cat',play:'Play effort',company:'Quiet company'}[kind];}
  updateLabel(){const leader=CatMood.keys.reduce((a,k)=>this.values[k]>this.values[a]?k:a,'playfulness'),runner=Math.max(...CatMood.keys.filter(k=>k!==leader).map(k=>this.values[k])),candidate=this.values[leader]<.3||this.values[leader]-runner<.1?'balanced':leader,current=this.values[this.label]||0;if(candidate===this.label||candidate!=='balanced'&&this.values[leader]<current+.1){this.pending=null;return;}if(this.pending!==candidate){this.pending=candidate;this.since=this.time;}else if(this.time-this.since>=2){this.label=candidate;this.pending=null;}}
  disturbance(event){if(!event?.id||this.seen.has(event.id))return false;this.seen.add(event.id);while(this.seen.size>64)this.seen.delete(this.seen.values().next().value);this.lastEvent=event.kind||'Disturbance';this.events.unshift({id:event.id,kind:event.kind,at:this.time});this.events.length=Math.min(30,this.events.length);if(!this.held)this.values.alertness=CatMood.clamp(this.values.alertness+.35*CatMood.clamp(event.intensity??1));return true;}
  landingChoice(bias=1){const v=this.values,weights=[['ignore',.6+v.sleepiness*1.3],['watch',.5+v.alertness*.7],['hop',(.15+v.alertness*.9+v.playfulness*.4)*Math.max(.1,Math.min(4,bias))]];let r=this.random()*weights.reduce((a,p)=>a+p[1],0);return weights.find(p=>(r-=p[1])<0)?.[0]||'ignore';}
  startleFollowup(){const v=this.values,weights=[['settle',.5+2*v.sleepiness],['retreat',.4+1.5*v.alertness],['counter',.15+2*v.playfulness*(1-v.sleepiness)]];let r=this.random()*weights.reduce((n,p)=>n+p[1],0);return weights.find(p=>(r-=p[1])<0)?.[0]||'settle';}
  view(){const v=this.values,sum=v.playfulness+v.sleepiness+v.alertness,colors=[[240,177,61],[169,117,225],[70,201,229]],rgb=[0,1,2].map(i=>Math.round(CatMood.keys.reduce((n,k,j)=>n+v[k]*colors[j][i],0)/Math.max(.001,sum)));return {values:{...v},label:this.label,held:this.held,seed:this.seed,lastEvent:this.lastEvent,color:sum<.3?'145,157,170':rgb.join(','),strength:.15+Math.max(...Object.values(v))*.5};}
}
const landingCue = (source,motion,recipient,id) => {
 const s=source.scale,r=recipient.scale,drop=motion.y-motion.fromY,a=motion.target,b=recipient.support;
 if(motion.kind!=='jump'||drop<16*s||!a?.el||!b?.el||Math.abs(a.top-b.top)>12*Math.max(s,r))return null;
 const x=motion.x+12*s,other=recipient.x+12*r;if(Math.hypot(x-other,a.top-b.top)>28*Math.max(s,r))return null;
 return {id,kind:'Nearby high landing',source:source.ownerKey,x,y:a.top,intensity:Math.min(1,drop/(60*s)),dropCells:drop/s};
};
